node -e '
const ALLOWED_TAGS=new Set(["p","ul","ol","li","strong","em","b","i"]);
const VOID_TAGS=new Set(["br"]);
const DROP=new Set(["script","style","template","noscript","iframe","object","embed","svg"]);
const VOID_ELEMENTS=new Set(["area","base","br","col","embed","hr","img","input","link","meta","param","source","track","wbr"]);
const LIST=new Set(["ul","ol"]);
const TAG_RE=/<(\/?)([a-zA-Z][a-zA-Z0-9-]*)((?:[^>"\x27]|"[^"]*"|\x27[^\x27]*\x27)*)>/g;
function parse(html){
 if(!html) return [];
 const root={tag:null,children:[]};const stack=[root];const top=()=>stack[stack.length-1];
 let dropTag=null,dropDepth=0;
 const pushText=(raw)=>{if(!raw)return;const p=top().tag;if(p&&LIST.has(p)&&!raw.trim())return;top().children.push(raw);};
 let cursor=0,m;TAG_RE.lastIndex=0;
 const closeTop=()=>{const f=stack.pop();if(!f||!f.tag)return;const p=top();p.children.push({t:f.tag,c:f.children});};
 while((m=TAG_RE.exec(html))!==null){
  const[full,closing,rawName,attrs]=m;const tag=rawName.toLowerCase();
  if(dropDepth===0)pushText(html.slice(cursor,m.index));
  cursor=m.index+full.length;
  if(dropDepth>0){if(tag===dropTag)dropDepth+=closing?-1:1;if(dropDepth===0)dropTag=null;continue;}
  if(DROP.has(tag)){if(!closing&&!VOID_ELEMENTS.has(tag)&&!attrs.trimEnd().endsWith("/")){dropTag=tag;dropDepth=1;}continue;}
  if(closing){if(!ALLOWED_TAGS.has(tag))continue;const d=stack.findIndex(f=>f.tag===tag);if(d<=0)continue;while(stack.length>d)closeTop();continue;}
  if(VOID_TAGS.has(tag)){top().children.push({t:tag,c:[]});continue;}
  if(!ALLOWED_TAGS.has(tag))continue;
  if(attrs.trimEnd().endsWith("/"))continue;
  stack.push({tag,children:[]});
 }
 if(dropDepth===0)pushText(html.slice(cursor));
 while(stack.length>1)closeTop();
 return root.children;
}
const ser=(n)=>Array.isArray(n)?n.map(ser).join(""):typeof n==="string"?n:`<${n.t}>${ser(n.c)}</${n.t}>`;
const cases=[
 ["nested list 2 inner items","<ul><li>a<ul><li>b</li><li>c</li></ul></li><li>d</li></ul>"],
 ["nested list 1 inner item","<ul><li>a<ul><li>b</li></ul></li><li>d</li></ul>"],
 ["nested ol in ul","<ul><li>x<ol><li>1</li><li>2</li></ol></li></ul>"],
 ["html comment","<!-- <script>x</script> -->visible"],
 ["word comment","<!--[if gte mso 9]><xml>junk</xml><![endif]-->Real copy"],
 ["plain comment","before<!-- internal note -->after"],
 ["nested strong","<strong>a<strong>b</strong>c</strong>"],
 ["p in p","<p>a<p>b</p>c</p>"],
 ["anchor link","See our <a href=\"/size-guide\">size guide</a> for details"],
 ["doctype","<!DOCTYPE html><p>hi</p>"],
 ["li with attr class","<ul><li class=\"x\">a</li></ul>"],
 ["unclosed script","<p>ok</p><script>evil()"],
 ["nbsp only","&nbsp;"],
];
for(const[n,i]of cases)console.log(n.padEnd(28),"|",JSON.stringify(ser(parse(i))));
'

